import json
import re
from collections import deque
from typing import Dict, List, Tuple, Any

SECTION_RE = re.compile(r"^\[(.+?)\]\s*$")
CHOICE_RE = re.compile(r"^\s*\d+\.\s*(.+?)\s*->\s*([A-Za-z0-9_]+)\s*$")
LINE_RE = re.compile(r"^([^:]+):\s*(.+?)\s*->\s*([A-Za-z0-9_]+)\s*$")


def _split_sections(text: str) -> List[Tuple[str, List[str]]]:
    sections: List[Tuple[str, List[str]]] = []
    current_id = None
    current_lines: List[str] = []

    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue
        m = SECTION_RE.match(line)
        if m:
            if current_id is not None:
                sections.append((current_id, current_lines))
            current_id = m.group(1).strip()
            current_lines = []
        else:
            current_lines.append(line)

    if current_id is not None:
        sections.append((current_id, current_lines))

    return sections


def parse_script(text: str) -> Dict[str, List[Dict[str, Any]]]:
    sections = _split_sections(text)
    nodes: Dict[str, Dict[str, str]] = {}
    edges: List[Dict[str, str]] = []

    for section_id, lines in sections:
        choices = []
        line_matches = []
        for line in lines:
            cm = CHOICE_RE.match(line)
            if cm:
                choices.append((cm.group(1).strip(), cm.group(2).strip()))
                continue
            lm = LINE_RE.match(line)
            if lm:
                line_matches.append((lm.group(1).strip(), lm.group(2).strip(), lm.group(3).strip()))
                continue
            # Unrecognized line format; ignore for now

        if choices:
            speaker = ""
            text_val = ""
            if line_matches:
                speaker, text_val, _ = line_matches[0]
            nodes[section_id] = {
                "id": section_id,
                "text": text_val,
                "speaker": speaker,
                "type": "choice",
            }
            for choice_text, target in choices:
                edges.append({"from": section_id, "to": target, "text": choice_text})
        else:
            speaker = ""
            text_val = ""
            target = ""
            if line_matches:
                speaker, text_val, target = line_matches[0]
                nodes[section_id] = {
                    "id": section_id,
                    "text": text_val,
                    "speaker": speaker,
                    "type": "line",
                }
                if target:
                    edges.append({"from": section_id, "to": target, "text": ""})
            else:
                nodes[section_id] = {
                    "id": section_id,
                    "text": "",
                    "speaker": "",
                    "type": "line",
                }

    # Create implicit nodes for missing targets
    targets = {e["to"] for e in edges if e.get("to")}
    for target in sorted(targets):
        if target not in nodes:
            nodes[target] = {
                "id": target,
                "text": "",
                "speaker": "",
                "type": "line",
            }

    # Ensure reachability from the first section
    if sections:
        start_id = sections[0][0]
        reachable = set()
        queue = deque([start_id])
        adjacency = {}
        for e in edges:
            adjacency.setdefault(e["from"], []).append(e["to"])
        while queue:
            nid = queue.popleft()
            if nid in reachable:
                continue
            reachable.add(nid)
            for nxt in adjacency.get(nid, []):
                if nxt not in reachable:
                    queue.append(nxt)

        nodes = {nid: node for nid, node in nodes.items() if nid in reachable}
        edges = [e for e in edges if e["from"] in nodes and e["to"] in nodes]

    return {
        "nodes": list(nodes.values()),
        "edges": edges,
    }


def _dot_escape(value: str) -> str:
    return value.replace("\\", "\\\\").replace('"', '\\"')


def build_dot(graph: Dict[str, List[Dict[str, Any]]]) -> str:
    lines = ["digraph Dialogue {"]
    lines.append("  rankdir=LR;")
    for node in graph["nodes"]:
        label_parts = [node["id"]]
        if node.get("type") == "choice":
            if node.get("text"):
                label_parts.append(f"{node.get('speaker', '')}: {node.get('text', '')}".strip())
            label_parts.append("[choice]")
        else:
            speaker = node.get("speaker", "").strip()
            text_val = node.get("text", "").strip()
            if speaker or text_val:
                label_parts.append(f"{speaker}: {text_val}".strip())
        label = "\\n".join([p for p in label_parts if p])
        lines.append(f"  \"{_dot_escape(node['id'])}\" [label=\"{_dot_escape(label)}\"];")

    for edge in graph["edges"]:
        if edge.get("text"):
            lines.append(
                f"  \"{_dot_escape(edge['from'])}\" -> \"{_dot_escape(edge['to'])}\" [label=\"{_dot_escape(edge['text'])}\"];")
        else:
            lines.append(
                f"  \"{_dot_escape(edge['from'])}\" -> \"{_dot_escape(edge['to'])}\";")

    lines.append("}")
    return "\n".join(lines)


def main() -> None:
    with open("/app/script.txt", "r", encoding="utf-8") as f:
        text = f.read()

    graph = parse_script(text)

    with open("/app/dialogue.json", "w", encoding="utf-8") as f:
        json.dump(graph, f, indent=2, ensure_ascii=True)

    dot_text = build_dot(graph)
    with open("/app/dialogue.dot", "w", encoding="utf-8") as f:
        f.write(dot_text)


if __name__ == "__main__":
    main()
